import urllib.request
for path in ['/', '/openapi.json', '/api', '/api/v1', '/api/v2', '/health', '/prices']:
    req = urllib.request.Request(f'http://192.168.0.3:8081{path}')
    try:
        with urllib.request.urlopen(req) as resp:
            print(path, resp.status, resp.read()[:100])
    except urllib.error.HTTPError as e:
        print(path, e.code, e.read()[:100])
    except Exception as e:
        print(path, e)
